  'פרסומים שממתינים לקבוצה הזו, והקבוצה תוסר גם מהתזמון הפעיל שיצר אותם — אחרת היא הייתה חוזרת לתור תוך דקה. אי אפשר להחזיר אותם — אפשר רק להוסיף את הקבוצה שוב לתור.': 'публикаций, ожидающих для этой группы, а группу уберём и из активного расписания, которое их создало — иначе она вернулась бы в очередь за минуту. Вернуть их нельзя — можно только добавить группу в очередь снова.',
  'פרסומים שנעצרו באמצע וממתינים להחלטה שלכם. הם לא עוצרים את התזמון — שאר הפרסומים ממשיכים לצאת בזמן. "הצג" פותח את הרשימה, וההתראה תחזור רק אם יצטרף פרסום חדש.': 'Публикации, остановившиеся на середине и ожидающие вашего решения. Расписание они не останавливают — остальные выходят в срок. «Показать» открывает список, а оповещение вернётся только если появится новая публикация.',
  'פרסומים שעדיין לא הגיע זמנם לא יוקדמו.': 'Публикации, чьё время ещё не пришло, раньше не выйдут.',
  'פרסומים תקועים חזרו לתור': 'Застрявшие публикации вернулись в очередь',
  'פרסומים תקועים שוחררו': 'Застрявшие публикации освобождены',
  'פתח את הפוסט שפורסם': 'Открыть опубликованный пост',
  'פתח את הקבוצה בפייסבוק': 'Открыть группу в Facebook',
  'פתחו את ההודעה ששלחנו ל־': 'Откройте письмо, отправленное на ',
  'פתחו את הקבוצה ובדקו שאתם חברים ושמותר לפרסם בה. אם לא — כבו אותה ברשימת הקבוצות.': 'Откройте группу и проверьте, что вы её участник и что в ней можно публиковать. Если нет — отключите её в списке групп.',
  'פתחו את חלון הדפדפן שנפתח במחשב (או לחצו "התחבר לפייסבוק"), טפלו באימות, ואז "בדוק שוב".': 'Откройте окно браузера, открывшееся на ПК (или нажмите «Войти в Facebook»), пройдите подтверждение, затем «Проверить снова».',
  'פתחו את חלון הדפדפן שנפתח במחשב, אשרו את מה שפייסבוק מבקשת, ואז "בדוק שוב" בלוח הבקרה.': 'Откройте окно браузера, открывшееся на ПК, подтвердите запрос Facebook, затем «Проверить снова» в панели управления.',
  'צא מהקבוצה בפייסבוק': 'Выйти из группы в Facebook',
  'צור ותזמן פוסט לקבוצות': 'Создать и запланировать пост для групп',
  'צור פוסט לקבוצה': 'Создать пост для группы',
  'צור פוסט לקבוצה הזו': 'Создать пост для этой группы',
  'צילום מסך של התקלה': 'Снимок экрана с ошибкой',
  'צפוי שהפרסום הזה יידחה למחר': 'Вероятно, эта публикация отложится на завтра',
  'צפי — התור עוד לא נבנה': 'Прогноз — очередь ещё не построена',
  'צרו פוסט בסבב, בחרו קבוצות ותזמנו — כל פרסום יופיע כאן עם השעה שלו.': 'Создайте пост в цикле, выберите группы и запланируйте — каждая публикация появится здесь со своим временем.',
  'צרו פוסט, בחרו קבוצות ולחצו "התחל פרסום" — התור יופיע כאן בזמן אמת.': 'Создайте пост, выберите группы и нажмите «Начать публикацию» — очередь появится здесь в реальном времени.',
  'צרו פוסט, בחרו קבוצות ותזמנו — השעה של הפרסום הבא תופיע כאן.': 'Создайте пост, выберите группы и запланируйте — время следующей публикации появится здесь.',
  'צריך לאשר את המייל קודם — חפשו הודעה מאיתנו בתיבה (גם בספאם) ולחצו על הקישור שבה.': 'Сначала подтвердите почту — найдите наше письмо в ящике (и в спаме) и нажмите на ссылку в нём.',
  'צריך להקליד מה לחפש — עיר, אזור או נושא.': 'Введите, что искать — город, район или тему.',
  'צריך להריץ את social-latest.sql ב-Supabase לפני שאפשר להוסיף תגובות. אפשר להריץ אותו שוב גם אם כבר הרצתם.': 'Перед добавлением комментариев нужно выполнить social-latest.sql в Supabase. Его можно выполнить снова, даже если уже выполняли.',
  'צריך להתחבר מחדש לפייסבוק': 'Нужно войти в Facebook заново',
