  'מהירות חדשה נשמרת מיד וחלה על כל מה שייכתב מכאן והלאה. פרסומים שכבר בתור שומרים על השעה שנכתבה להם — לכיווץ תור קיים יש ״הגדרות תור מתקדמות״ בכרטיס הסבב.': 'Новая скорость сохраняется сразу и действует на всё, что будет записано далее. Публикации, уже стоящие в очереди, сохраняют назначенное им время — чтобы сжать существующую очередь, используйте «Расширенные настройки очереди» в карточке цикла.',
