  'מצב הפרסום "§" נשמר לחשבון, אבל לא הצלחתי לסנכרן אותו לסבבים עצמם — סבב עם מרווח איטי יותר ימשיך לפרסם בקצב שלו עד שתיגעו בכרטיס שלו. §': 'Режим публикации "§" сохранён для аккаунта, но синхронизировать его с циклами не удалось — цикл с более медленным интервалом продолжит публиковать в своём темпе, пока не тронете его карточку. §',
