  '; § לא נוספו ונשארו בתיבה': '; § не добавлены и остались в поле',
  'Supabase חסמה את הפרויקט (§) כי הוא עבר מכסה חודשית (402). זאת הסיבה שאי אפשר להיכנס, והסיסמה שלכם בסדר. צריך להיכנס ללוח הבקרה של Supabase, לראות ב-Reports → Usage איזו מכסה נגמרה, ולשדרג את התוכנית או לחכות למחזור החיוב הבא.': 'Supabase заблокировал проект (§): превышена месячная квота (402). Поэтому войти нельзя, а пароль в порядке. Зайдите в панель Supabase, посмотрите в Reports → Usage, какая квота закончилась, и повысьте тариф или дождитесь следующего расчётного периода.',
