  '§ § בהיסטוריה — המסך הזה טוען רק את הראשונות.': '§ § в истории — экран загружает только первые.',
  '§ § בלי אישור מפייסבוק. פתחו את הפוסט ובדקו לפני שתוסיפו שוב — ייתכן שהן כבר שם.': '§ § без подтверждения от Facebook. Загляните в пост, прежде чем добавлять снова — возможно, они уже там.',
  '§ § לסוף התור.': '§ § в конец очереди.',
