  '§ התראות חדשות': '§ новых оповещений',
  '§ ואף אחד מהם לא יֵצא: הפרסום לקבוצות נעשה מהדפדפן שעל המחשב שלכם. פתחו את התיקייה ולחצו פעמיים על start-worker.cmd, והשאירו את החלון פתוח.': '§ и ни одна из них не выйдет: в группы публикует браузер на вашем ПК. Откройте папку, дважды щёлкните по start-worker.cmd и оставьте окно открытым.',
  '§ זו המכסה לריצה אחת — הרץ שוב להמשך.': '§ — лимит одного запуска. Запустите снова, чтобы продолжить.',
