  '§ פרסומים הוזזו ל§, אבל § לא זזו: §': '§ {публикация|публикации|публикаций} перенесено на §, но § не сдвинулись: §',
  '§ פרסומים לא נכתבו לתור — הסיבה רשומה בשורה האדומה שלידה. ההפצה ההדרגתית לא נסגרה, ננסה שוב בבדיקה הבאה.': '§ {публикация|публикации|публикаций} не {записана|записаны|записаны} в очередь — причина в красной строке рядом. Постепенная рассылка не закрыта, повторим при следующей проверке.',
  '§ פרסומים לא נכתבו לתור — הסיבה רשומה בשורה האדומה שלידה. הסבב לא נסגר, ננסה שוב בבדיקה הבאה.': '§ {публикация|публикации|публикаций} не {записана|записаны|записаны} в очередь — причина в красной строке рядом. Цикл не закрыт, повторим при следующей проверке.',
  '§ פרסומים נמצאים בסטטוס שאף worker לא יאסוף — הם לעולם לא יצאו בלי טיפול ידני': '§ {публикация|публикации|публикаций} в статусе, который не возьмёт ни один worker — {она|они|они} никогда не {выйдет|выйдут|выйдут} без обработки вручную',
