  '§ פרסומים שטרם התחילו יבוטלו.': 'Отменим § {ещё не начатую публикацию|ещё не начатые публикации|ещё не начатых публикаций}.',
  '§ פרסומים שטרם יצאו יבוטלו': '§ {ещё не вышедшая публикация отменится|ещё не вышедшие публикации отменятся|ещё не вышедших публикаций отменятся}',
