type Compiled = { re: RegExp; out: string; countSlots: number[] };

let compiled: Compiled[] | null = null;
let anchorRe: RegExp | null = null;

function esc(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** The longest run of literal text in a pattern — what identifies it cheaply. */
function longestLiteral(pattern: string): string {
  let best = '';
  for (const part of pattern.split(PH)) if (part.length > best.length) best = part;
  return best;
}

/*
 * ─── WHAT A § MAY AND MAY NOT SWALLOW ───────────────────────────────────
 *
 * A § used to be `[\s\S]*?` — anything at all — and that let one thin
 * pattern eat a whole sentence. Measured on the real dashboard:
 *
 *   on screen   · פורסם ל-204 מתוך 252 קבוצות היום · 48 קבוצות עוד לא קיבלו…
 *   came out    · פורסם ל-204 из 252 קבוצות היום · 48 קבוצות ещё не Получили…
 *
 * `§ מתוך §` matched the entire line, took "· פורסם ל-204" as one value and
 * everything after "252" as the other, and printed Hebrew and Russian
 * interleaved. Five patterns matched that one line.
 *
 * The app joins separate facts with " · " and " | ". A value never spans
 * them — a value is a number, a time, a percentage or a name — so a § may
 * not cross one. That is what stops a pattern meant for "5 מתוך 12" from
 * claiming a line of six facts, and it costs nothing: a group name has no
 * bullet in it.
 */
const SLOT = '([^·|\\n]*?)';

function compile(): Compiled[] {
  if (compiled) return compiled;
  const rows = Object.entries(RU_PAT)
    /* Longest literal text first: the most specific shape wins a tie. */
    .sort((a, b) => b[0].replace(/§/g, '').length - a[0].replace(/§/g, '').length);
  compiled = rows.map(([he, ru]) => ({
    re: new RegExp('^' + he.split(PH).map(esc).join(SLOT) + '$'),
    out: ru,
    /*
     * ─── A COUNT IS A NUMBER, NEVER A WORD ──────────────────────────────
     *
     * `§ שניות` is "N seconds", and its literal half is one short noun. On
     * the real dashboard it matched a CAMPAIGN NAME that happens to end the
     * same way — "סבב כל 30 שניות" — and printed half of the customer's own
     * name back as "סבב כל 30 секунд". Nothing about the dictionary looked
     * wrong; the shape simply fitted.
     *
     * WHICH PATTERNS ARE COUNTS IS ALREADY WRITTEN DOWN, in the Russian: a
     * counted noun carries its three forms in braces, and a noun only needs
     * three forms because a number stands in front of it. So there is no
     * second list to keep in step — a pattern that picks a plural form is a
     * pattern whose value is a number, and its value may not contain a
     * Hebrew word.
     *
     * Everything else is left alone, because a slot is often MEANT to hold
     * the customer's words: a group name in one, the name of a day in
     * another.
     */
    /*
     * WHICH slots those are is read off the Russian, not guessed. `fill()`
     * settles a braced noun against the value immediately before it, so a
     * brace in part i is governed by value i-1 and only THAT value has to be
     * a number. The old rule asked about the first value whatever the braces
     * governed, and it was wrong in both directions:
     *
     *   '§ בכל מועד, אחד כל § · § מועדים בשבועיים הקרובים'
     *
     * puts a count in the THIRD slot and a counted phrase ("292 יעדים") in
     * the first, so the whole line was skipped and the screen kept the
     * Hebrew half of a sentence whose Russian was sitting right here.
     *
     * A brace in part 0 has nothing before it; fill() gives it the third
     * form and there is no value to check.
     */
    countSlots: ru
      .split(PH)
      .map((part, i) => (i > 0 && HAS_PLURAL.test(part) ? i - 1 : -1))
      .filter((i) => i >= 0),
  }));
  const anchors = [...new Set(rows.map(([he]) => longestLiteral(he)).filter((a) => a.trim().length >= 1))];
  anchorRe = anchors.length ? new RegExp(anchors.map(esc).join('|')) : null;
  return compiled;
}

/*
 * THE VALUE INSIDE A PATTERN CAN ITSELF BE A SENTENCE WE KNOW.
 *
 *     `${counted(...)} ל${movedTo ?? 'שעות החדשות'}`
 *
 * The outer shape is a pattern; what lands in the slot is sometimes a group
 * name — the customer's own words, which must be left exactly alone — and
 * sometimes a phrase of ours that has its own translation. So each captured
 * value is looked up as a sentence and as a pattern, and kept as it is when
 * neither answers. A group called "ניקוי ספות באר שבע" is in no dictionary
 * and comes through untouched; "שעות החדשות" is, and turns Russian.
 *
 * ONE LEVEL ONLY, so a value can never send the matcher round again.
 */
/*
 * A dictionary entry is written as it appears on its own — "Завтра",
 * "Получили" — so it is capitalised. Dropped into the middle of a sentence
 * that reads as one, the capital is wrong, and it was visible on the real
 * campaign card: "следующий цикл откроется Завтра (שלישי)". Only a Cyrillic
 * word is lowered, and only when the rest of it is already lowercase, so
 * "Facebook" and "Meta" are never touched.
 */
function midSentence(ru: string): string {
  const first = ru.charAt(0);
  if (!/[А-ЯЁ]/.test(first)) return ru;
  const rest = ru.slice(1);
  if (rest !== rest.toLowerCase()) return ru;
  return first.toLowerCase() + rest;
}

function translateValue(value: string, atStart: boolean, depth = 1): string {
  const trimmed = value.trim();
  if (!trimmed) return value;
  const exact = RU[trimmed];
  /*
   * ONE MORE LEVEL, and no further. "הסבב הבא ייפתח מחר (שלישי)," puts a
   * date inside a sentence and the name of a day inside the date; without
   * the second level the screen read "откроется завтра (שלישי)". The depth is
   * counted rather than trusted, so a dictionary that one day pointed at
   * itself could not spin here.
   */
  const inner =
    exact ??
    (depth > 0 ? matchPattern(trimmed, true, depth - 1) : matchPattern(trimmed, false)) ??
    translateCommaList(trimmed) ??
    withoutDecoration(trimmed);
  if (inner === null || inner === undefined) return value;
  const pre = /^\s*/.exec(value)?.[0] ?? '';
  const post = /\s*$/.exec(value)?.[0] ?? '';
  return pre + (atStart ? inner : midSentence(inner)) + post;
}

/*
 * ─── A NUMBER CHANGES THE NOUN IN RUSSIAN ────────────────────────────────
 *
 * Hebrew has one plural and Russian has three, chosen by the number in front
 * of the noun. Writing a single form means two thirds of the counts on screen
 * are wrong: "3 групп" instead of "3 группы", "21 групп" instead of
 * "21 группа". It is not a missing translation, which is why it survives a
 * coverage guard — it is a wrong one, and a Russian speaker reads it as
 * broken software.
 *
 * So a counted noun is written as the three forms in braces, in this order:
 *
 *     '§ קבוצות': '§ {группа|группы|групп}'
 *
 * and the form is chosen by the value substituted just before it. A value
 * that is not a whole number (a time, a name) takes the third form, which is
 * the one Russian uses with "сколько" and reads correctly on its own.
 */
const PLURAL = /\{([^{}|]*)\|([^{}|]*)\|([^{}|]*)\}/g;
/* The same shape without /g, so .test() does not carry a lastIndex between calls. */
const HAS_PLURAL = /\{[^{}|]*\|[^{}|]*\|[^{}|]*\}/;

/** Russian's own rule, by the last digits of the number. */
function plural(forms: [string, string, string], value: string): string {
  const n = Math.abs(Number(value.replace(/[\s, ]/g, '')));
  if (!Number.isInteger(n)) return forms[2];
  const hundred = n % 100;
  if (hundred >= 11 && hundred <= 14) return forms[2];
  const ten = n % 10;
  if (ten === 1) return forms[0];
  if (ten >= 2 && ten <= 4) return forms[1];
  return forms[2];
}

/**
 * Puts the captured values into the Russian, and settles every counted noun
 * against the value that precedes it.
 */
function fill(out: string, values: string[]): string {
  const parts = out.split(PH);
  let text = parts[0];
  /* Before the first value there is nothing to agree with, so a noun there
     takes the third form rather than guessing. */
  text = text.replace(PLURAL, (_m, a, b, c) => plural([a, b, c], ''));
  for (let i = 1; i < parts.length; i += 1) {
    const value = values[i - 1] ?? '';
    text += value + parts[i].replace(PLURAL, (_m, a, b, c) => plural([a, b, c], value));
  }
  return text;
}

/**
 * Runs the patterns over one line of Hebrew. Returns null when none fits, so
 * the caller can fall back to the Hebrew rather than show a half-translation.
 * `deep` translates the captured values too, and is false when this is
 * already running on a captured value.
 */
function matchPattern(hebrew: string, deep: boolean, depth = 1): string | null {
  const rows = compile();
  /* One regex decides whether any pattern is even worth trying. Without this
     a DOM walk would run 400 regexes over every text node on the page. */
  if (!anchorRe || !anchorRe.test(hebrew)) return null;
  for (const { re, out, countSlots } of rows) {
    const m = re.exec(hebrew);
    if (!m) continue;
    if (countSlots.some((i) => /[\u0590-\u05FF]/.test(m[i + 1] ?? ''))) continue;
    /* Where each value lands in the Russian decides whether it keeps its
       capital: at the very start of the line, or after a full stop, it does. */
    const parts = out.split(PH);
    const values = m.slice(1).map((v, i) => {
      if (!deep) return v;
      const before = parts[i] ?? '';
      /*
       * WHAT STANDS IN FRONT OF THIS VALUE is not always the pattern's own
       * words. Where two slots sit side by side — "טרם פורסם · § §", 84 and
       * then דולגו — the stretch between them is one space, which read as
       * "nothing before it, so this starts a sentence" and capitalised a word
       * in the middle of a line: the library tile said "Ещё не вышло · 84
       * Пропущены". What is really in front of it is the PREVIOUS VALUE, so
       * that is what the question is asked about; a previous value that ends
       * in a full stop still starts a sentence here, which is the case this
       * rule exists for.
       */
      const front = i > 0 && before.trim() === '' ? `${m[i] ?? ''}${before}` : before;
      const atStart = front.trim() === '' || /[.!?:]\s*$/.test(front);
      return translateValue(v, atStart, depth);
    });
    return fill(out, values);
  }
  return null;
}

/*
 * ─── A BULLET IN FRONT, A COMMA BEHIND ──────────────────────────────────
 *
 * The screens glue decoration onto sentences they already hold:
 *
 *   on screen   "· אין פרסומים מתוכננים"      dictionary   "אין פרסומים מתוכננים"
 *   on screen   "מחר (שלישי),"                pattern      "מחר (§)"
 *
 * Both came out in Hebrew in the middle of a Russian screen, because one
 * bullet or one comma is enough for a key to miss. Rather than list every
 * decorated variant, the decoration is set aside, the sentence inside is
 * translated, and the decoration is put back exactly as it was. The inside
 * still has to be a sentence the dictionary knows, so nothing is guessed.
 */
/*
 * The dash list holds the ASCII hyphen AND the two the screens really use:
 * "— הפרסום מושהה." came out in Hebrew on a Russian screen while
 * "הפרסום מושהה." sat in the dictionary, because an em dash was not
 * decoration as far as this regex was concerned.
 *
 * AND THE QUESTION MARK IS DECORATION TOO, which a screenshot found rather
 * than a measurement. GroupCard prints a city it had to GUESS as the city
 * with a "?" after it (`${cityLabel}?`), and that one character meant the
 * dictionary's "באר שבע" was never reached: on the Russian groups screen,
 * beside tiles reading "Мицпе-Рамон" and "Беэр-Шева", the guessed one still
 * read "באר שבע?". A key that really ends in a question mark is matched
 * exactly first, and a pattern is tried before this, so nothing that was
 * already answered changes.
 */
const DECORATED = /^([·•*\-–—\s]*)([\s\S]*?)([,.:;?!\s]*)$/;

function withoutDecoration(hebrew: string): string | null {
  const m = DECORATED.exec(hebrew);
  if (!m) return null;
  const [, lead, core, tail] = m;
  if (!core || (!lead && !tail)) return null;
  const inner = RU[core] ?? matchPattern(core, true);
  if (inner === null || inner === undefined) return null;
  return lead + inner + tail;
}

/*
 * ─── A LINE OF FACTS IS A LIST, NOT A SENTENCE ──────────────────────────
 *
 * The dashboard's summary line is built by joining separate facts:
 *
 *   · פורסם ל-204 מתוך 252 קבוצות היום · 48 קבוצות עוד לא קיבלו פרסום ·
 *     271 פרסומים דולגו · 3 פרסומים נכשלו · 252 פרסומים עוד לא יצאו
 *
 * On screen that is ONE text node, and as one sentence it is hopeless: the
 * numbers change, the facts come and go, and no dictionary could hold every
 * combination. As a LIST it is easy — each fact between the bullets is a
 * sentence the dictionary already knows or can match.
 *
 * So a bulleted line is split, each fact is translated on its own, and the
 * line is put back together with its bullets where they were. A fact nobody
 * knows stays in Hebrew, which is the same fallback as everywhere else: part
 * of the line in Russian is honest, and nothing is mangled, because a § can
 * no longer cross a bullet either.
 */
/* The two separators the screens join independent facts with. */
const SEPARATORS = [' · ', ' | '];

function translateList(hebrew: string): string | null {
  for (const sep of SEPARATORS) {
    if (!hebrew.includes(sep)) continue;
    let changed = false;
    const out = hebrew.split(sep).map((fact) => {
      /* A fact may itself be a list joined with the other separator. */
      const one = translateList(fact) ?? translateOne(fact);
      if (one !== fact) changed = true;
      return one;
    });
    if (changed) return out.join(sep);
  }
  return null;
}

/*
 * A comma-joined list of things the dictionary knows, all or nothing. The
 * weekday row is written "א׳, ב׳, ג׳, ד׳, ה׳" and every part of it has an
 * entry; translating some and not others would read worse than leaving it.
 */
function translateCommaList(hebrew: string): string | null {
  if (!hebrew.includes(', ')) return null;
  const parts = hebrew.split(', ');
  if (parts.length < 2) return null;
  const out: string[] = [];
  for (const part of parts) {
    const hit = RU[part.trim()];
    if (hit === undefined) return null;
    out.push(hit);
  }
  return out.join(', ');
}

/*
 * ─── THE SCREEN HAS QUOTES; THE SOURCE HAS &quot; ─────────────────────────
 *
 * Some of these sentences are written in JSX as HTML entities, because that
 * is how a quote inside JSX text is spelled:
 *
 *   source   חוץ מ&quot;בתור&quot;, שהוא התור כפי שהוא עכשיו
 *   screen   חוץ מ"בתור", שהוא התור כפי שהוא עכשיו
 *
 * The dictionary is keyed by the source, so the key and the screen differ by
 * five characters and the line stayed Hebrew. The entities are expanded and
 * the sentence is looked up again, so both spellings reach the same entry.
 */
const ENTITIES: [RegExp, string][] = [
  [/&quot;/g, '"'],
  [/&apos;/g, "'"],
  [/&amp;/g, '&'],
  [/&nbsp;/g, '\u00a0'],
  [/&ndash;/g, '\u2013'],
  [/&mdash;/g, '\u2014'],
];

function byEntityKey(hebrew: string): string | null {
  for (const [key, value] of Object.entries(RU)) {
    if (!key.includes('&')) continue;
    let expanded = key;
    for (const [re, ch] of ENTITIES) expanded = expanded.replace(re, ch);
    if (expanded === hebrew) return value;
  }
  return null;
}

/** One sentence: exactly, by shape, as a comma list, or with its decoration set aside. */
function translateOne(hebrew: string): string {
  const exact = RU[hebrew];
  if (exact !== undefined) return exact;
  const byPattern = matchPattern(hebrew, true);
  if (byPattern !== null) return byPattern;
  const byList = translateCommaList(hebrew);
  if (byList !== null) return byList;
  const byEntity = byEntityKey(hebrew);
  if (byEntity !== null) return byEntity;
  return withoutDecoration(hebrew) ?? hebrew;
}

/*
 * ─── A NAME INSIDE A SENTENCE WE DO TRANSLATE ─────────────────────────────
 *
 * data-no-translate protects what is PAINTED, because an element can carry an
 * attribute. An aria-label cannot: it is one string, and the screens build
 * some of them out of our words and the customer's together —
 *
 *     aria-label={`בחר את ${group.name}`}
 *
 * — so the dictionary answered the whole thing, slot and all, and a group the
 * customer really called "באר שבע ביחד" was announced to a screen reader, and
 * shown in a desktop tooltip, as "Выбрать наш район". The name is in the
 * dictionary because it is the group-name field's own placeholder.
 *
 * keep() marks a piece of such a string as the customer's. The marks are
 * U+2068 and U+2069 — invisible isolate characters, the same family this file
 * already uses for direction in ltr() — so nothing on screen changes and no
 * call site has to know what the translator does with them.
 *
 * WHAT THE TRANSLATOR DOES is the trick: a marked piece becomes a § before
 * anything is looked up, which turns "בחר את <name>" into the shape the
 * dictionary already holds, and the piece is put back AFTER the sentence has
 * been translated — untouched, never looked up, in the place the Russian puts
 * its §. One mechanism, no new dictionary entries, and the matcher did not
 * have to learn anything.
 */
const KEEP_OPEN = '\u2068';
const KEEP_CLOSE = '\u2069';
const KEEP_RE = /\u2068([^\u2069]*)\u2069/g;

/** Marks a piece of a composed string as the customer's own words. */
export function keep(text: string): string {
  return `${KEEP_OPEN}${text}${KEEP_CLOSE}`;
}

/** The same string with the marks taken out, for anything that reads it raw. */
export function unkeep(text: string): string {
  return text.replace(KEEP_RE, '$1');
}

/** The Hebrew sentence when there is no Russian for it — never an empty slot. */
export function translate(lang: Lang, hebrew: string): string {
  if (KEEP_RE.test(hebrew)) {
    KEEP_RE.lastIndex = 0;
    const kept: string[] = [];
    const masked = hebrew.replace(KEEP_RE, (_m, inner: string) => {
      kept.push(inner);
      return PH;
    });
    if (lang === 'he') return unkeep(hebrew);
    const out = translate(lang, masked);
    let i = 0;
    return out.replace(/§/g, () => kept[i++] ?? '');
  }
  KEEP_RE.lastIndex = 0;
  if (lang === 'he') return hebrew;
  const exact = RU[hebrew];
  if (exact !== undefined) return exact;
  /*
   * A PATTERN FOR THE WHOLE LINE COMES FIRST, before the line is taken apart.
   * "§ חברים · ציבורית" is written as one shape on purpose — the words after
   * the bullet belong to the same phrase and read lowercase there — and
   * splitting first translated each half on its own and capitalised the
   * second. Safe to try first, because a § can no longer cross a bullet: a
   * pattern reaches a bulleted line only when it carries the bullet itself.
   */
  const whole = matchPattern(hebrew, true);
  if (whole !== null) return whole;
  const asList = translateList(hebrew);
  if (asList !== null) return asList;
  return translateOne(hebrew);
}

/** Every Hebrew sentence this dictionary can answer. Read by the tests. */
export function translatedKeys(): string[] {
  return Object.keys(RU);
}

/** Every Hebrew pattern this dictionary can answer. Read by the tests. */
export function translatedPatterns(): string[] {
  return Object.keys(RU_PAT);
}

/** The Russian written for one fixed sentence, with no pattern involved. */
export function translatedValue(hebrew: string): string | undefined {
  return RU[hebrew];
}

/** The Russian written for one pattern, slots and all. Read by the tests. */
export function translatedPatternValue(pattern: string): string | undefined {
  return RU_PAT[pattern];
}

/* ─── the store ──────────────────────────────────────────────────────────
 *
 * A module store rather than a React context, for one concrete reason: a
 * provider would have to be mounted in src/app/social/layout.tsx, a file
 * every screen in the app renders through, and this task may not put a new
 * wrapper around all of them. Components subscribe to this instead and
 * nothing above them changes.
 */
let current: Lang = 'he';
let booted = false;
const listeners = new Set<() => void>();

function emit() {
  for (const l of listeners) l();
}

/** Applies the choice to the document, which is what makes Russian read LTR. */
function applyToDocument(lang: Lang) {
  if (typeof document === 'undefined') return;
  document.documentElement.setAttribute('lang', lang);
  document.documentElement.setAttribute('dir', dirOf(lang));
}

export function getLang(): Lang {
  return current;
}

export function setLang(lang: Lang): void {
  if (lang !== 'he' && lang !== 'ru') return;
  current = lang;
  try {
    window.localStorage.setItem(LANG_KEY, lang);
  } catch {
    /* a locked-down browser may refuse storage; the choice still applies to
       this page, it just will not survive a reload. Never a crash. */
  }
  applyToDocument(lang);
  emit();
}

/*
 * READ ONCE, AFTER HYDRATION, ON PURPOSE.
 *
 * The server renders Hebrew because it cannot know the choice. If this store
 * answered "ru" during hydration the markup would not match what the server
 * sent and React would discard it. So the first paint is always Hebrew and
 * the stored choice is applied immediately after — one frame, no mismatch.
 */
export function bootLang(): void {
  if (booted || typeof window === 'undefined') return;
  booted = true;
  let saved: string | null = null;
  try {
    saved = window.localStorage.getItem(LANG_KEY);
  } catch {
    saved = null;
  }
  if (saved === 'ru' || saved === 'he') {
    current = saved;
    applyToDocument(saved);
    emit();
  }
}

function subscribe(fn: () => void) {
  listeners.add(fn);
  return () => {
    listeners.delete(fn);
  };
}

export function useLang(): Lang {
  return useSyncExternalStore(
    subscribe,
    () => current,
    () => 'he' as Lang,
  );
}

/*
 * THE PLAIN FUNCTION, for the 61 screens that simply print sentences.
 *
 * A hook in every one of them would mean inserting a line into 61 component
 * bodies by regex — and a component body is exactly the thing a regex gets
 * wrong. So screens call this, and <LangBoundary> re-keys the app when the
 * language changes, which re-renders them all. The price is that a switch
 * remounts the tree; it is a deliberate, rare action, and the alternative was
 * rewriting 61 files blind.
 *
 * Reactive callers (the sign-in screen) keep useT() and do not need the
 * remount at all.
 */
export function t(hebrew: string): string {
  return translate(current, hebrew);
}

/** `const t = useT()` — then `t('ברוכים הבאים')`. */
export function useT(): (hebrew: string) => string {
  const lang = useLang();
  return useCallback((hebrew: string) => translate(lang, hebrew), [lang]);
}
